#include "sa3t_texture.h"
#include <string.h>
#define SA3T_HEADER_SIZE 64u
#define SA3T_DESC_SIZE 24u
#define SA3T_RGBA8 1u
static uint16_t r16(const uint8_t*p){return(uint16_t)(p[0]|((uint16_t)p[1]<<8));}
static uint32_t r32(const uint8_t*p){return(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
SA3TResult sa3t_open(SA3TArchive*out,const void*data,size_t size){if(!out||!data)return SA3T_ERR_ARGUMENT;memset(out,0,sizeof(*out));if(size<SA3T_HEADER_SIZE)return SA3T_ERR_TRUNCATED;const uint8_t*p=data;if(memcmp(p,"SA3T",4)||r16(p+4)||r16(p+6)||r32(p+8)!=SA3T_HEADER_SIZE||r32(p+16)!=(uint32_t)size)return SA3T_ERR_HEADER;uint32_t n=r32(p+12);if((size_t)SA3T_HEADER_SIZE+(size_t)n*SA3T_DESC_SIZE>size)return SA3T_ERR_TRUNCATED;out->data=p;out->size=size;out->texture_count=n;memcpy(out->source_sha256,p+20,32);for(uint32_t i=0;i<n;i++){SA3TTexture t;const uint8_t*d=p+SA3T_HEADER_SIZE+(size_t)i*SA3T_DESC_SIZE;t.width=r16(d);t.height=r16(d+2);t.format=r16(d+4);t.flags=r16(d+6);t.data_offset=r32(d+8);t.data_size=r32(d+12);t.source_pixel_format=r16(d+16);t.source_data_format=r16(d+18);t.global_index=r32(d+20);if(t.format!=SA3T_RGBA8||t.data_size!=(uint32_t)t.width*(uint32_t)t.height*4u)return SA3T_ERR_FORMAT;if((t.data_offset&15u)||t.data_offset<SA3T_HEADER_SIZE+n*SA3T_DESC_SIZE||(size_t)t.data_offset+t.data_size>size)return SA3T_ERR_RANGE;}return SA3T_OK;}
SA3TResult sa3t_texture(const SA3TArchive*a,uint32_t i,SA3TTexture*out,const uint8_t**rgba8){if(!a||!a->data||!out||!rgba8)return SA3T_ERR_ARGUMENT;if(i>=a->texture_count)return SA3T_ERR_RANGE;const uint8_t*d=a->data+SA3T_HEADER_SIZE+(size_t)i*SA3T_DESC_SIZE;out->width=r16(d);out->height=r16(d+2);out->format=r16(d+4);out->flags=r16(d+6);out->data_offset=r32(d+8);out->data_size=r32(d+12);out->source_pixel_format=r16(d+16);out->source_data_format=r16(d+18);out->global_index=r32(d+20);if((size_t)out->data_offset+out->data_size>a->size)return SA3T_ERR_RANGE;*rgba8=a->data+out->data_offset;return SA3T_OK;}
const char*sa3t_result_name(SA3TResult r){switch(r){case SA3T_OK:return"OK";case SA3T_ERR_ARGUMENT:return"ARGUMENT";case SA3T_ERR_TRUNCATED:return"TRUNCATED";case SA3T_ERR_HEADER:return"HEADER";case SA3T_ERR_RANGE:return"RANGE";case SA3T_ERR_FORMAT:return"FORMAT";default:return"UNKNOWN";}}
